11	/* Props for each wizard are taken verbatim from the components themselves, so the
12	   hub can never drift from what a wizard actually expects. The deploy page computes
13	   these identically to how each product's old page did — this component only relays
14	   them. None of the checkout / charge / first-month-free logic lives here. */
15	type VpsProps = React.ComponentProps<typeof DeployWizard>;
16	type HostingProps = React.ComponentProps<typeof HostingDeployWizard>;
17	type GameProps = React.ComponentProps<typeof GameDeployWizard>;
