108	/* ── Isometric server-stack hero illustration. Pure SVG so it themes cleanly and
109	      needs no asset. Three stacked blades on an iso base with glowing brand edges,
110	      status LEDs and a soft ground glow — reads clearly as a server. To swap in a
111	      real render later, replace this element with <img src="…" /> — nothing else
112	      depends on it. */
113	function ServerRackArt({ className }: { className?: string }) {
114	  // Three stacked iso blades; each is a top face + front face + side face.
115	  const blades = [0, 1, 2];
116	  return (
117	    <svg viewBox="0 0 320 300" fill="none" xmlns="http://www.w3.org/2000/svg" className={className} aria-hidden>
118	      <defs>
119	        <linearGradient id="hubTop" x1="0" y1="0" x2="1" y2="1">
120	          <stop offset="0" stopColor="#1b2646" />
121	          <stop offset="1" stopColor="#121a34" />
122	        </linearGradient>
123	        <linearGradient id="hubFront" x1="0" y1="0" x2="0" y2="1">
124	          <stop offset="0" stopColor="#131c38" />
125	          <stop offset="1" stopColor="#0b1226" />
126	        </linearGradient>
127	        <linearGradient id="hubSide" x1="0" y1="0" x2="0" y2="1">
128	          <stop offset="0" stopColor="#0d1428" />
129	          <stop offset="1" stopColor="#080d1c" />
130	        </linearGradient>
131	        <linearGradient id="hubEdge" x1="0" y1="0" x2="1" y2="1">
132	          <stop offset="0" stopColor="#8a70fb" />
133	          <stop offset="1" stopColor="#22d3ee" />
134	        </linearGradient>
135	        <radialGradient id="hubGlow" cx="0.5" cy="0.5" r="0.5">
136	          <stop offset="0" stopColor="#6f47f5" stopOpacity="0.55" />
137	          <stop offset="1" stopColor="#6f47f5" stopOpacity="0" />
138	        </radialGradient>
139	      </defs>
140	
141	      {/* ground glow */}
142	      <ellipse cx="160" cy="256" rx="120" ry="30" fill="url(#hubGlow)" />
143	
144	      {blades.map((b) => {
145	        // iso projection: each blade sits 46px higher than the last.
146	        const oy = 190 - b * 46;
147	        const dx = 120; // half-width along the iso X
148	        const dz = 60; // depth along iso Y
149	        const h = 26; // blade thickness (front face)
150	        const cx = 160;
151	        // key points of the top rhombus
152	        const top = `${cx},${oy - dz / 2} ${cx + dx},${oy} ${cx},${oy + dz / 2} ${cx - dx},${oy}`;
153	        const led = b === 1 ? "#22d3ee" : "#8a70fb";
154	        return (
155	          <g key={b}>
156	            {/* top face */}
157	            <polygon points={top} fill="url(#hubTop)" stroke="url(#hubEdge)" strokeWidth="1.25" strokeOpacity="0.6" />
158	            {/* front-left face */}
159	            <polygon
160	              points={`${cx - dx},${oy} ${cx},${oy + dz / 2} ${cx},${oy + dz / 2 + h} ${cx - dx},${oy + h}`}
161	              fill="url(#hubFront)"
162	            />
163	            {/* front-right face */}
164	            <polygon
165	              points={`${cx},${oy + dz / 2} ${cx + dx},${oy} ${cx + dx},${oy + h} ${cx},${oy + dz / 2 + h}`}
166	              fill="url(#hubSide)"
167	            />
168	            {/* glowing seam along the front bottom edge */}
169	            <polyline
170	              points={`${cx - dx},${oy + h} ${cx},${oy + dz / 2 + h} ${cx + dx},${oy + h}`}
171	              stroke="url(#hubEdge)"
172	              strokeWidth="1.5"
173	              strokeOpacity="0.85"
174	              fill="none"
175	            />
176	            {/* drive slots on the left face */}
177	            {[0, 1, 2].map((s) => (
178	              <line
179	                key={s}
180	                x1={cx - dx + 16 + s * 30}
181	                y1={oy + 12 + (16 + s * 30) * (dz / 2 / dx)}
182	                x2={cx - dx + 30 + s * 30}
183	                y2={oy + 12 + (30 + s * 30) * (dz / 2 / dx)}
184	                stroke="#2b3a63"
185	                strokeWidth="3"
186	                strokeLinecap="round"
187	              />
188	            ))}
189	            {/* status LEDs on the right face */}
190	            <circle cx={cx + dx - 16} cy={oy + 13} r="3.2" fill={led}>
191	              <animate attributeName="opacity" values="0.4;1;0.4" dur={`${2 + b * 0.5}s`} repeatCount="indefinite" />
192	            </circle>
193	            <circle cx={cx + dx - 16} cy={oy + 21} r="3.2" fill="#22d3ee" opacity="0.5" />
194	          </g>
195	        );
196	      })}
197	    </svg>
198	  );
199	}
200	
201	export function DeployHub({
202	  vps,
203	  hosting,
204	  game,
205	  email,
206	  hostingPromoOn = false,
207	}: {
208	  /** null when no active plans/images are configured (VPS deploy unavailable). */
209	  vps: VpsProps | null;
210	  hosting: HostingProps;
211	  /** null when no game families have active tiers. */
212	  game: GameProps | null;
213	  email: EmailProps;
214	  /** The first-month-free promo is RUNNING (offer exists) — drives the marketing
215	   *  "1st month free" badge on the Shared Hosting tab. The actual $0-vs-full price
216	   *  at checkout stays gated per-account/IP (hosting.firstMonthFree). */
217	  hostingPromoOn?: boolean;
218	}) {
219	  const router = useRouter();
220	  const searchParams = useSearchParams();
221	  const initial = searchParams.get("product");
222	  const [active, setActive] = useState<DeployProduct>(isProduct(initial) ? initial : "vps");
223	
224	  const select = useCallback(
225	    (p: DeployProduct) => {
226	      setActive(p);
227	      // Deep-link without a full navigation so the mounted wizard/state is preserved.
228	      const params = new URLSearchParams(Array.from(searchParams.entries()));
229	      params.set("product", p);
230	      router.replace(`/dashboard/deploy?${params.toString()}`, { scroll: false });
231	    },
232	    [router, searchParams]
233	  );
234	
235	  const activeAccent = ACCENTS[active];
236	
237	  const wizard = useMemo(() => {
238	    // Only the ACTIVE product's wizard is ever mounted.
239	    switch (active) {
240	      case "vps":
241	        return vps ? (
242	          <DeployWizard {...vps} />
243	        ) : (
244	          <EmptyState
245	            title="Deployments are temporarily unavailable"
246	            sub="No active plans or images are configured. Please check back soon or contact support."
247	          />
248	        );
249	      case "hosting":
250	        return (
251	          <div className="space-y-3">
252	            {/* Display-only promo banner — the charge decision lives in orderHostingAccount.
253	                Shown only when THIS user is eligible (firstMonthFreeEligible), computed on
254	                the deploy page exactly as the old hosting page did. */}
255	            {hosting.firstMonthFree && hosting.plans.length > 0 && (
256	              <div className="flex items-center gap-2 rounded-xl border border-emerald-500/25 bg-emerald-500/10 px-3 py-2 text-sm font-medium text-emerald-300">
257	                <span className="flex h-1.5 w-1.5 shrink-0 rounded-full bg-emerald-400 animate-pulse-dot" />
258	                Your first month is free on shared hosting — then the price you sign up at is the price you renew at.
259	              </div>
260	            )}
261	            <HostingDeployWizard {...hosting} />
262	          </div>
263	        );
264	      case "game":
265	        return game ? (
266	          <GameDeployWizard {...game} />
267	        ) : (
268	          <EmptyState
269	            title="No game plans available yet"
270	            sub="Game server plans aren't configured yet. Check back soon, or open a ticket and we'll let you know when they're live."
271	          />
272	        );
273	      case "email":
274	        // On the deploy page this is an ORDER surface only — the subscription /
275	        // mailbox management list lives on /dashboard/email (linked in the header).
276	        return <EmailHosting {...email} showSubscriptions={false} />;
277	    }
278	  }, [active, vps, hosting, game, email]);
279	
280	  return (
281	    <div className="space-y-6">
282	      {/* ── Compact hero + product selector in one panel ─────────────────────── */}
283	      <section className="relative overflow-hidden rounded-3xl border border-white/[0.06] bg-navy-900/60 p-4 sm:p-5">
284	        <div aria-hidden className="hero-aura pointer-events-none absolute inset-0" />
285	        {/* Decorative server-stack, confined to the HEADER band (top-right) and faded
286	            left so it never sits behind the product cards below — keeps the hero clean. */}
287	        <ServerRackArt className="pointer-events-none absolute right-1 top-1 hidden h-[132px] w-auto opacity-25 [mask-image:linear-gradient(to_left,black_55%,transparent)] lg:block" />
288	
289	        {/* slim header row */}
290	        <div className="relative flex flex-wrap items-center justify-between gap-3 px-1">
291	          <div className="min-w-0">
292	            <span className="eyebrow-pill mb-2">
293	              <span className="h-1.5 w-1.5 rounded-full bg-accent-cyan animate-pulse-dot" /> Nxeon · Deploy
294	            </span>
295	            <h1 className="text-2xl font-black tracking-tight text-white sm:text-[1.7rem]">
296	              <span className="grad-text">Deploy</span> Your Server
297	            </h1>
298	          </div>
299	          <p className="max-w-xs text-sm leading-relaxed text-slate-400">
300	            Launch a VPS, shared-hosting site, game server, or business email in minutes.
301	          </p>
302	        </div>
303	
304	        {/* product selector: the four cards ARE the tabs */}
305	        <div role="tablist" aria-label="Product" className="relative mt-4 grid gap-2.5 sm:grid-cols-2 lg:grid-cols-4">
306	          {PRODUCTS.map((id) => {
307	            const a = ACCENTS[id];
308	            const isActive = active === id;
309	            return (
310	              <button
311	                key={id}
312	                role="tab"
313	                aria-selected={isActive}
314	                onClick={() => select(id)}
315	                className={`group relative flex items-start gap-3 rounded-2xl border bg-navy-950/50 p-3.5 text-left transition-all ${
316	                  isActive ? a.activeCard : "border-white/[0.06] hover:border-white/15"
317	                }`}
318	              >
319	                <span className={`inline-flex h-10 w-10 flex-none items-center justify-center rounded-xl bg-gradient-to-br text-white ${a.tile} ${a.tileGlow}`}>
320	                  <a.Icon className="h-5 w-5" />
321	                </span>
322	                <span className="min-w-0">
323	                  <span className="flex items-center gap-1.5">
324	                    <span className={`text-sm font-semibold ${isActive ? "text-white" : "text-slate-100"}`}>{a.label}</span>
325	                    {id === "hosting" && hostingPromoOn ? (
326	                      <span className="rounded-full border border-emerald-500/40 bg-emerald-500/15 px-1.5 py-0.5 text-[9px] font-semibold uppercase tracking-wide text-emerald-300">
327	                        1st Month Free
328	                      </span>
329	                    ) : (
330	                      a.badge && (
331	                        <span className={`rounded-full border px-1.5 py-0.5 text-[9px] font-semibold uppercase tracking-wide ${a.badge.cls}`}>
332	                          {a.badge.text}
333	                        </span>
334	                      )
335	                    )}
336	                  </span>
337	                  <span className="mt-0.5 block text-xs leading-snug text-slate-400">{a.desc}</span>
338	                  <span className={`mt-1.5 inline-flex items-center gap-1 text-xs font-medium transition-transform group-hover:translate-x-0.5 ${a.text}`}>
339	                    {isActive ? "Selected" : "Choose"} <span aria-hidden>→</span>
340	                  </span>
341	                </span>
342	              </button>
343	            );
344	          })}
345	        </div>
346	
347	      </section>
348	
349	      {/* ── Active product's wizard ──────────────────────────────────────────── */}
350	      <div>
351	        {/* No repeated product-name heading here — the product card row above
352	            (and its "Selected" state) already identifies which wizard is active;
353	            a second label right above the step indicator was pure redundancy. */}
354	        {active === "email" && (
355	          <div className="mb-4 flex justify-end">
356	            <a
357	              href="/dashboard/email"
358	              className="inline-flex items-center gap-1 text-xs font-medium text-blue-300 hover:text-blue-200"
359	            >
360	              Manage your email subscriptions →
361	            </a>
362	          </div>
363	        )}
364	        {wizard}
365	      </div>
366	    </div>
367	  );
368	}
