40	
41	type Plan = {
42	  id: string; name: string; cpuCores: number; ramMB: number; diskGB: number;
43	  bandwidthTB: number; priceCents: number; storageTier: string;
44	};
45	type Image = {
46	  id: string; slug: string; name: string; category: string; family: string;
47	  version: string; logo: string; minRamMB: number; minDiskGB: number;
48	  licenseRequired: boolean; featured: boolean;
49	};
50	type NodeOpt = { id: string; name: string; publicIp: string };
51	
52	// USD formatter — this wizard's long-standing 2-decimal style ("$5.00"). Used
53	// verbatim for the USD display path (so USD renders byte-for-byte unchanged) and
54	// for the "billed in USD" reference note. `money()` (defined per-render inside the
55	// component, currency-aware) is what the UI actually calls.
56	const usd = (c: number) => `$${(c / 100).toFixed(2)}`;
57	
58	/** sessionStorage key for the in-progress order — see the restore effect below. */
59	const DRAFT_KEY = "nxeon.deploy.draft.v1";
60	type Draft = {
61	  step: number;
62	  planId: string;
63	  nodeId: string;
64	  imageId: string;
65	  tab: string;
66	  addons: { malware: boolean; backup: boolean; docker: boolean };
67	  dedicatedIp: boolean;
68	  extraDiskGB: number;
69	  hostname: string;
70	  pubKey: string;
71	  termMonths: number;
72	  useWallet: boolean;
73	  /** A confirmed custom plan, carried through the Stripe cancel round-trip since
74	   *  it's never in the server-fetched `plans` prop (see the `customPlan` state
75	   *  doc comment above). Null when the customer picked a premade plan. */
76	  customPlan: Plan | null;
77	};
78	
79	/**
80	 * APPLICATION-category images with one of these families are split into the
81	 * Games tab instead of Applications. Sourced from lib/games.ts's GAME_FAMILIES
82	 * — the single canonical list of all game families (19, not just the original
83	 * 6) — rather than a local copy-pasted set. A local copy here previously only
84	 * knew about minecraft/valheim/rust/palworld/cs2/terraria, so every game added
85	 * since (ARK, Satisfactory, Project Zomboid, 7 Days to Die, V Rising,
86	 * Enshrouded, Factorio, Garry's Mod, Conan Exiles, Unturned, The Forest, Sons
87	 * of the Forest, Minecraft Bedrock) silently fell through into Applications,
88	 * duplicating what the Games tab (and the dedicated Game Server product) already
89	 * list properly. Importing the shared list keeps this in sync by construction.
90	 */
91	const GAME_FAMILIES = new Set<string>(GAME_FAMILY_LIST);
92	
