351	    if (!checkoutActions) return;
352	    setError(null);
353	    setConfirming(true);
354	    try {
355	      const result = await checkoutActions.confirm({ savePaymentMethod: saveCard });
356	      if (result.type === "error") setError(result.error.message ?? "Your card was declined. Please try another payment method.");
357	      // On success Stripe navigates the browser to the session's return_url
358	      // (/api/stripe/confirm) — the SAME route that fulfils every other Stripe
359	      // payment on this platform. Nothing else to do here.
360	    } catch {
361	      setError("Something went wrong confirming your payment. Please try again.");
362	    } finally {
363	      setConfirming(false);
364	    }
365	  }
366	
367	  return (
368	    <>
369	      <MethodRow
370	        id="card"
371	        selected={selected === "card"}
