387	                  paymentMethodOrder: ["card"],
388	                }}
389	              />
390	            </div>
391	          </div>
392	          <div>
393	            <label className="mb-1.5 block text-xs font-medium text-slate-400">Cardholder name</label>
394	            <input
395	              type="text"
396	              value={name}
397	              onChange={(e) => setName(e.target.value)}
398	              placeholder="Name on card"
399	              className="w-full rounded-lg border border-white/[0.08] bg-white/[0.02] px-3 py-2 text-sm text-slate-200 placeholder:text-slate-600 focus:border-brand-400/50 focus:outline-none"
400	            />
401	          </div>
402	          <label className="flex items-start gap-2.5 rounded-lg border border-white/[0.06] bg-white/[0.02] px-3 py-2.5">
403	            <input type="checkbox" checked={saveCard} disabled className="mt-0.5 h-3.5 w-3.5 accent-brand-500" onChange={(e) => onToggleSaveCard(e.target.checked)} />
404	            <span className="text-xs text-slate-400">
405	              <span className="font-medium text-slate-300">Save card for faster checkout</span>
406	              <br />
407	              {saveCardExplainer}
408	            </span>
409	          </label>
410	          {error && <p className="rounded-lg border border-red-500/25 bg-red-500/10 px-3 py-2 text-xs text-red-300">{error}</p>}
411	          <button
412	            type="button"
413	            onClick={payWithCard}
414	            disabled={confirming || !checkoutActions?.canConfirm}
415	            className="btn-deploy w-full py-3 text-sm"
416	          >
417	            <LockIcon className="h-4 w-4" />
418	            {confirming ? "Processing…" : `Pay Securely ${money(totalDueCents)}`}
419	            {!confirming && <span className="dep-arrow">→</span>}
420	          </button>
421	        </div>
422	      </MethodRow>
423	
424	      {/*
425	        ONE ExpressCheckoutElement, always mounted, showing whichever wallets
426	        the browser/device actually supports (Stripe renders them side by
427	        side itself). This used to be TWO separate elements — one per wallet,
428	        each shown only when its own MethodRow was the "selected" radio
429	        option — which looked static (nothing to click until you clicked the
430	        row first) and, worse, having both mount at once (needed to fix the
431	        static look) throws Stripe's own "cannot create multiple instances of
432	        the Express Checkout Element" error. A single instance covering both
433	        wallets is Stripe's actual supported shape for this. Hidden entirely
434	        (via onReady's availablePaymentMethods) when NEITHER wallet is
435	        available on this browser/device/card.
436	      */}
437	      {/* Always mounted (never conditionally unmounted) so onReady gets a
438	          chance to fire at all — only its VISIBILITY is gated on the result,
