442	          <ExpressCheckoutElement
443	            options={{
444	              // The /checkout subpath's ExpressCheckoutElementOptions requires
445	              // every key present (unlike the main package's), even though
446	              // Stripe treats undefined the same as omitted for each of these.
447	              buttonHeight: undefined,
448	              buttonTheme: undefined,
449	              buttonType: undefined,
