462	              setError(null);
463	              const result = await checkoutActions.confirm({ expressCheckoutConfirmEvent: event });
464	              if (result.type === "error") setError(result.error.message ?? "Payment failed.");
465	            }}
466	          />
467	      </div>
468	    </>
469	  );
470	}
