17	 *
18	 * Visibility rules (see the effect below for the full state machine):
19	 *   - Shows the "provisioning" phase whenever the server is in a transitional
20	 *     status. Sets a sessionStorage flag so a REFRESH mid-provision still
21	 *     shows it (not just the initial mount).
22	 *   - Shows "success" the moment that flag is set AND the status flips to
23	 *     RUNNING — OR, for the case where the server was ALREADY done by the
24	 *     time this page first loaded (real orders provision in under two
25	 *     minutes, but this platform's SANDBOX mode completes instantly), when
26	 *     the URL carries the `purchase=1` marker `reportPurchase` already stamps
27	 *     onto every real paid-order redirect.
28	 *   - Never shown for a customer just casually revisiting an old, already-
29	 *     running server — that's the whole reason for the two gates above
30	 *     instead of "status === RUNNING".
31	 *   - Once dismissed, stays dismissed for this server (sessionStorage),
32	 *     surviving a refresh.
33	 */
34	export function ProvisioningOverlay({
35	  serverId,
36	  status,
37	  transitional,
38	  justPaid,
