84	  extraInfo?: { label: string; value: string; href?: string }[];
85	  /** The status value that means "done, show the success card" — "RUNNING" for a
86	   *  VPS/game server, "ACTIVE" for a Shared Hosting account. */
87	  readyStatus?: string;
88	  /** Real (never fake/invented) current-step label, e.g. "Cloning your server…" or
89	   *  "Installing WordPress…" — sourced from lib/provisioning-step.ts. Replaces the
90	   *  cosmetic time-based cycling text in the provisioning view when present; null
91	   *  falls back to that cosmetic text (no real signal available yet). */
92	  liveStep?: string | null;
93	  /** True while a real, product-specific step is still in progress even though
94	   *  `transitional` (account/server status) has already gone false — e.g. Shared
95	   *  Hosting's account is ACTIVE but a just-ordered WordPress install is still
96	   *  running as a queued task. Only ever extends the provisioning view while this
97	   *  session was already watching (or just paid) — see the effect below — so a
98	   *  LATER, casual action (installing an app months on) never hijacks the screen. */
