102	}) {
103	  const storageKey = `nxeon:overlay:${serverId}`;
104	  const [phase, setPhase] = useState<"hidden" | "provisioning" | "success">("hidden");
105	  const mountedAtRef = useRef<number | null>(null);
106	  // Real infra provisions in well under this — it's purely a perceived-progress
107	  // floor so the animation never flashes by unreadably fast (e.g. SANDBOX mode,
108	  // which completes instantly), not a claim about how long the real work takes.
109	  const MIN_PROVISIONING_MS = 3200;
110	
111	  useEffect(() => {
112	    let watching = false;
113	    try {
114	      watching = sessionStorage.getItem(storageKey) === "watching";
115	    } catch {
116	      /* storage disabled — degrade to "never show" rather than guess */
117	    }
118	
119	    if (transitional) {
120	      if (mountedAtRef.current == null) mountedAtRef.current = Date.now();
121	      setPhase("provisioning");
122	      try {
123	        sessionStorage.setItem(storageKey, "watching");
124	      } catch {
125	        /* ignore */
126	      }
127	      return;
128	    }
129	
130	    // Not transitional anymore (by the base status alone). Before deciding this is
131	    // done, check for a real, product-specific follow-on step still running — e.g.
132	    // Shared Hosting's account just flipped ACTIVE but a WordPress install queued
133	    // at order time is still processing. Gated on watching/justPaid, same as the
134	    // block above: this must never resurrect the full-screen takeover for a LATER,
135	    // casual action (installing an app months after purchase) — only for a follow-
136	    // on step that belongs to the SAME order this session was already watching.
137	    if (liveStepActive && (watching || justPaid) && sessionStorage.getItem(storageKey) !== "dismissed") {
138	      setPhase("provisioning");
139	      return;
140	    }
141	
142	    // Only earn a success screen if we were either actively watching this order
143	    // provision, or just landed here from a real paid checkout (the
144	    // sandbox-instant-complete case).
145	    if (status === readyStatus && (watching || justPaid) && sessionStorage.getItem(storageKey) !== "dismissed") {
