179	    <div className="fixed inset-0 z-[100] flex items-center justify-center overflow-y-auto bg-navy-950/90 p-4 backdrop-blur-md">
180	      <div className="card glow-brand relative w-full max-w-md motion-safe:animate-panel-in">
181	        {phase === "provisioning" ? (
