330	export async function login(
331	  prev: any,
332	  formData: FormData,
333	): Promise<{ error?: string; needs2fa?: boolean }> {
334	  const parsed = credsSchema.safeParse({
335	    // Same canonical form the account was stored under (lib/email-normalize.ts).
336	    // Without this, signing in as `Alice@Example.com` missed a row stored as
337	    // `alice@example.com` and reported bad credentials for a correct password.
338	    email: normalizeEmail(formData.get("email")),
339	    password: formData.get("password"),
340	  });
341	  if (!parsed.success) return { error: "Invalid email or password." };
342	
343	  // App-level throttle per email+IP over a 15 min window. The max-attempts cap is
344	  // admin-configurable (`login_ratelimit_max`, default 10) rather than hardcoded.
345	  //
346	  // The IP comes from `clientIp` (lib/rate-limit.ts), NEVER from
347	  // `x-forwarded-for.split(",")[0]`. nginx forwards the header with
348	  // `$proxy_add_x_forwarded_for`, which APPENDS the peer it saw to whatever the
349	  // client sent — so the leftmost entry is a free-text field the caller filled
350	  // in, and keying on it meant an attacker could rotate one header value per
351	  // request and never bind this limiter at all. That is the limiter standing
352	  // between a known email address and unlimited password guesses, and (below)
353	  // unlimited 2FA code guesses once a password is known. See the docblock on
354	  // `clientIp` for the measurement.
355	  const rlId = `${parsed.data.email}:${clientIp(await headers())}`;
356	  const maxAttempts = Math.max(1, await getSettingInt("login_ratelimit_max", 10));
357	  const rl = checkRateLimit(`login:${rlId}`, { max: maxAttempts, windowMs: 15 * 60 * 1000 });
358	  if (!rl.ok) return { error: `Too many attempts. Try again in ${rl.retryAfterSec}s.` };
359	
360	  const user = await db.user.findUnique({ where: { email: parsed.data.email } });
361	  // ALWAYS spend one bcrypt comparison, even when the address does not exist.
362	  //
363	  // `!user || !(await bcrypt.compare(...))` short-circuits: with no account, bcrypt
364	  // never ran. The reply text was correctly identical either way, but the reply
365	  // TIME was not — bcrypt at cost 12 is ~250ms against a single indexed SELECT, a
366	  // gap one sample per address is enough to read. That turns the login form into
367	  // an account-enumeration oracle: "does this person bank here", answered for any
368	  // address, at scale, without ever guessing a password.
369	  //
370	  // It was materially worse while the throttle above was keyed on the
371	  // caller-supplied first hop of `x-forwarded-for`, because the rate limit that
372	  // would otherwise cap sampling could itself be stepped around per request. That
373	  // is fixed, but a defence that only works because another defence works is not
374	  // one, so the timing is equalised on its own terms.
375	  //
376	  // The comparison against DUMMY_HASH is discarded — it exists solely to spend the
377	  // same ~250ms. Keep the reply string identical to the wrong-password case.
378	  const passwordOk = user
379	    ? await bcrypt.compare(parsed.data.password, user.passwordHash)
380	    : ((await bcrypt.compare(parsed.data.password, DUMMY_PASSWORD_HASH)), false);
381	  // `!user` is repeated here purely so TypeScript narrows `user` for the code
382	  // below. It is NOT a short-circuit any more: `passwordOk` above has already
383	  // spent the bcrypt comparison in both branches, which is the whole point.
384	  if (!user || !passwordOk) {
385	    return { error: "Invalid email or password." };
386	  }
387	  if (user.suspended) return { error: "This account is suspended." };
388	
389	  // Two-factor challenge, if enabled on the account.
390	  if (user.totpEnabled) {
391	    const code = String(formData.get("code") ?? "").trim();
392	    if (!code) return { error: "Enter your 2FA code to continue.", needs2fa: true };
393	    if (!(await verifyTotpForUser(user.id, code))) {
394	      return { error: "Invalid 2FA code.", needs2fa: true };
395	    }
396	  }
397	
398	  resetRateLimit(`login:${rlId}`);
399	  await audit(user.id, "user.login");

