517	  const user = await requireUser();
518	  // Spend path: never move a customer's money while an admin is impersonating them.
519	  // Caught (not left to throw uncaught) so an impersonating admin sees this exact
520	  // message inline — the bare throw used to crash the whole page with a generic
521	  // "Something went wrong" screen instead, a real bug hit every time an admin
522	  // testing the wizard while impersonating tried to pay.
523	  try {
524	    await assertNotImpersonating();
