526	    return { error: e instanceof Error ? e.message : "This action is disabled while impersonating a customer." };
527	  }
528	  // Same verification gate every purchase path applies. This is the CARD path, so it is the
529	  // one where an unreachable address is most expensive: without it we would take
530	  // a real payment for a machine whose credentials have nowhere to go.
531	  const unverified = await emailVerificationError(user);
532	  if (unverified) return { error: unverified };
