130	/* ------------------------------------------------------------------ *
131	 * The return leg from Stripe
132	 * ------------------------------------------------------------------ */
133	
134	type FinalizeState =
135	  | { kind: "working" }
136	  | { kind: "saved"; label: string }
137	  | { kind: "failed"; error: string };
138	
139	/**
140	 * Completes card setup after Stripe redirects back to
141	 * `/dashboard/billing?card_setup=<session_id>`.
142	 *
143	 * Two things this must not be:
144	 *  - a silent no-op. Checkout attaches the card at Stripe BEFORE this ever runs,
145	 *    so a customer who lands here and sees nothing has a card at Stripe and none
146	 *    on file with us — and would be dunned for it.
147	 *  - a dead end. If finalising fails, the card may still be saved at Stripe, and
148	 *    the worker's `adoptUnclaimedCards` backstop claims it on the next sweep. The
149	 *    failure copy says exactly that, and still offers a retry.
150	 *
151	 * `finalizeCardSetup` is documented as safe to call repeatedly with the same
152	 * session id, so a refreshed tab re-reads the same payment method rather than
153	 * saving a second card. The ref below is not for correctness, only to stop React's
154	 * development double-mount from firing two identical round-trips.
155	 */
156	export function CardSetupReturn({ sessionId }: { sessionId: string }) {
157	  const router = useRouter();
158	  const fired = useRef(false);
159	  const [state, setState] = useState<FinalizeState>({ kind: "working" });
160	  const canceled = sessionId === "canceled";
161	
162	  useEffect(() => {
163	    if (canceled || fired.current) return;
164	    fired.current = true;
165	    void (async () => {
166	      const res = await finalizeCardSetup(sessionId);
167	      if (res.ok) {
168	        setState({ kind: "saved", label: res.label ?? "Card saved" });
169	        // Fire-and-forget "card" conversion (→ Meta AddPaymentInfo + the Google Ads
170	        // card label). Best-effort: a no-op until consent + the pixel load.
171	        try {
172	          (window as unknown as { nxTrack?: (k: string, p?: Record<string, unknown>) => void }).nxTrack?.("card", {});
173	        } catch {
174	          /* ignore */
175	        }
176	        // Drop the one-shot session id from the URL so a refresh or a shared link
177	        // doesn't replay the return leg, then pull the page's server data again —
178	        // the action has already revalidated it.
179	        router.replace("/dashboard/billing");
180	        router.refresh();
181	        return;
182	      }
183	      setState({ kind: "failed", error: res.error ?? "The card wasn't saved." });
184	    })();
185	  }, [sessionId, canceled, router]);
186	
187	  if (canceled) {
188	    return (
189	      <div className="card border-amber-500/30 bg-amber-500/[0.06]">
190	        <p className="text-sm font-medium text-amber-300">Card setup canceled</p>
191	        <p className="mt-1 text-sm text-slate-400">
192	          No card was saved and nothing was charged. Your renewals will keep coming out of your
193	          wallet balance until a card is on file.
194	        </p>
195	        <div className="mt-3">
196	          <AddCardButton label="Try again" className="btn-secondary py-1.5" />
197	        </div>
198	      </div>
199	    );
200	  }
201	
202	  if (state.kind === "working") {
203	    return (
204	      <div className="card border-white/[0.08] text-sm text-slate-400">
205	        Finishing card setup — one moment.
206	      </div>
207	    );
208	  }
209	
210	  if (state.kind === "saved") {
211	    return (
212	      <div className="card border-emerald-500/30 bg-emerald-500/[0.06]">
213	        <p className="text-sm font-medium text-emerald-300">{state.label} saved</p>
214	        <p className="mt-1 text-sm text-slate-400">
215	          Renewals will now charge this card for anything your wallet balance doesn&apos;t cover.
216	        </p>
217	      </div>
218	    );
219	  }
220	
221	  return (
222	    <div className="card border-red-500/30 bg-red-500/[0.06]">
223	      <p className="text-sm font-medium text-red-300">We couldn&apos;t finish saving your card</p>
224	      <p className="mt-1 text-sm text-slate-400">{state.error}</p>
225	      <p className="mt-2 text-xs text-slate-500">
226	        If you completed the form on Stripe&apos;s page, the card may already be saved on their side
227	        — we check for that automatically and it will appear here within a few minutes. Nothing was
228	        charged either way.
229	      </p>
230	      <div className="mt-3">
231	        <AddCardButton label="Try again" className="btn-secondary py-1.5" />
232	      </div>
233	    </div>
234	  );
235	}
