238	 * Settle an outstanding balance
239	 * ------------------------------------------------------------------ */
240	
241	/**
242	 * Pay an overdue renewal now, on Stripe's hosted page.
243	 *
244	 * The link is minted fresh on every click rather than reusing the stored
245	 * `dunningPayUrl`, because Checkout sessions expire in 24 hours while the dunning
246	 * sequence runs for six days — see `settleOutstanding`.
247	 *
248	 * `covered: true` is NOT a failure: it means the wallet already funds the renewal
249	 * and the sweep will apply it. It gets neutral styling, not an error colour.
250	 */
251	export function SettleNowButton({
252	  serverId,
253	  className = "btn-primary py-1.5 text-xs",
254	}: {
255	  serverId: string;
256	  className?: string;
257	}) {
258	  const [message, setMessage] = useState<{ tone: "info" | "error"; text: string } | null>(null);
259	  const [checkout, setCheckout] = useState<{ clientSecret: string; publishableKey: string } | null>(null);
260	  const [pending, start] = useTransition();
