270	      }
271	      setMessage({
272	        tone: res.covered ? "info" : "error",
273	        text: res.error ?? "We couldn't start checkout. Please try again in a moment.",
274	      });
275	    });
276	  };
277	
278	  return (
279	    <div>
280	      <button className={className} onClick={pay} disabled={pending}>
281	        {pending ? "Opening checkout…" : "Pay now"}
282	      </button>
283	      {message && (
